// Serveur web sur un module Ethernet W5500 : la page montre la position du potentiomètre.
#include <SPI.h>
#include <Ethernet.h>

byte mac[] = { 0xDE, 0xAD, 0xBE, 0xEF, 0xFE, 0xED }; // une adresse MAC différente pour chaque module du réseau
EthernetServer serveur(80);                          // le port du web

void setup() {
  Serial.begin(9600);
  Ethernet.init(10);                 // CS du W5500 sur D10
  if (Ethernet.begin(mac) == 0) {    // adresse demandée à la box (DHCP)
    Serial.println("Pas de serveur DHCP");
    while (true) delay(1);
  }
  serveur.begin();
  Serial.print("Page web : http://");
  Serial.println(Ethernet.localIP());
}

void loop() {
  EthernetClient client = serveur.available();
  if (client) {
    boolean ligneVide = true;
    while (client.connected()) {
      if (client.available()) {
        char c = client.read();
        if (c == '\n' && ligneVide) {   // fin de la requête : une ligne vide
          int valeur = analogRead(A0);
          client.println("HTTP/1.1 200 OK");
          client.println("Content-Type: text/html; charset=utf-8");
          client.println("Connection: close");
          client.println();
          client.print("<h1>Atelier</h1><p>Potentiometre : ");
          client.print(valeur);
          client.println("</p>");
          break;
        }
        if (c == '\n') ligneVide = true;
        else if (c != '\r') ligneVide = false;
      }
    }
    delay(1);
    client.stop();
  }
}

text.fr:
Le W5500 consomme environ **130 mA** en 3,3 V ; la broche 3V3 de l’Uno ne donne que **50 mA** (le vérificateur le signale : J0109). Le régulateur U1 fait du 3,3 V à partir du 5 V :
- **IN** de U1 au **5V** de l’Uno (le câblage automatique le fait par la breadboard) ;
- **OUT** de U1 au **3V3** du W5500 : déplacez le fil 3V3 du module de la carte vers OUT de U1.

text.en:
The W5500 draws about **130 mA** at 3.3 V; the Uno’s 3V3 pin only gives **50 mA** (the checker reports it: J0109). Regulator U1 makes 3.3 V from 5 V:
- U1 **IN** to the Uno’s **5V** (auto-wiring does it through the breadboard);
- U1 **OUT** to the W5500’s **3V3**: move the module’s 3V3 wire from the board to U1 OUT.

